请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-006

=== 用户原始指令 (query.txt) ===
搞个阅读进度卡 要有看完百分之多少的数字 一行就行 点一下能跳进应用里

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个阅读进度卡 要有看完百分之多少的数字 一行就行 点一下能跳进应用里",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "reading": {
      "title": {
        "type": "string",
        "description": "阅读进度卡片的短标题。",
        "sampleValue": "阅读进度"
      },
      "progressText": {
        "type": "string",
        "description": "已看完内容所占百分比的展示文本。",
        "sampleValue": "64%"
      },
      "progressValue": {
        "type": "number",
        "description": "阅读完成进度的数值。",
        "sampleValue": 64
      },
      "progressTotal": {
        "type": "number",
        "description": "阅读完成进度的总量基准。",
        "sampleValue": 100
      },
      "entryText": {
        "type": "string",
        "description": "进入应用的短入口提示。",
        "sampleValue": "打开"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/music_fill.svg",
      "description": "音乐音符实心图标，可作为阅读听书类音频入口的候选 glyph 素材。"
    }
  ]
}

